(105, 44, 430, 437, 51.4167, 32, 83.4167, 'how are the hazard categories specified?\ndeBERTa is a pretrained model. how will you fine tune this model to get better results?\nyou picked GMA and Rappler because they are &quot;credible&quot;. what are the criteria you made to say that they are &quot;credible&quot;?\nSystem: Location name must be pinned on the map, not typed by user. It is also better if you can locate them using GPS\nConfidence Level: where is the data for that being taken?\nActivity Logs: where the logs for whoever approved/rejected a user report? how about other activities like adding RSS feeds, printing reports, etc?\nScope and Limitation: how about technical specification limits? (ROM, RAM, Screen Resolution, Operating Systems, etc.)\nCited Studies: all studies must be at most 5 years old (2020-2025)\n', '2025-12-06 02:04:15', '2026-02-12 22:04:49'),
