(158, 47, 430, 423, 48.75, 34, 82.75, '- don&#039;t be too nervous when presenting. take a deep breath and calm down.\n- the discussion doesn&#039;t include the discussion on all types of color blindness and which ones are being focused on this study.\n- have a recommended mobile device where this app can perform flawlessly (especially on the screen specs since you&#039;ll be conducting a clinical trial).\n- no comparison with existing mobile apps\n- no mentions of model training, testing, how the models interact with one another\n- no mentions of the datasets used\n- no mentions of why the proponents &quot;modified&quot; the dataset to make the colors &quot;harder&quot;\n- no comparison of models with the unaltered dataset and altered dataset\n- no mentions of fine tuning\n- no mentions of how the system works with the model\n\nApp: \n- the disclaimer must be AT THE TOP of the screen, not below the navigation bar\n- The system has no indication that the system is working with the model\n- the color identification doesn&#039;t work properly.', '2025-12-06 08:28:32', '2026-02-12 22:04:49'),
