(170, 48, 441, 443, 47.5833, 33, 80.5833, '1. How are the camera feeds will be accessed? same network as city&#039;s cctv network or via internet?\n2. Will this be processed real-time or utilizes the stored videos? Why? Pros and Cons?\n3. Minimum hardware requirements if utilizing real-time camera stream?\n4. What are the current camera resolution does the city have in place? given the camera resolution, what\n5. will be the minimum distance from camera to person to make it recognizable?\n6. Deployment plan - hosted locally or cloud? Hardware specs required?\n7. How PNP will be able to access the system from CICTO? or will alert them automatically? via internet if setup as accessible\n   through the internet, or are they on the same network?\n8. Which DB is used? What data is stored?\n9. Any sensitive information you&#039;ll be storing?\n    Any testing / evaluation if the alert results are correct?\n10. What security measures will be in place?\n11. What type of alert? email, text, telegram?\n\n\n\n\n', '2025-12-06 09:48:23', '2026-02-12 22:04:49'),
