(178, 48, 430, 443, 47.5, 32, 79.5, '- chapter 1 was discussed by only 1 person?\n- there are 17 cases from 2020 to 2024. is there really a need for this system to exist?\n\n- no comparison made for existing facial recognition systems like NeoFace, Au10tixs, FaceVACS\n- no visualization on how the system works and how the models interact with each other\n- no mentions of the datasets used to train and test the models\n- no mentions on how the models will be fine-tuned for better performance\n- no mentions of the diagrams and their explanation (use case, context diagram, data flow diagram, system development life cycle, etc.)', '2025-12-06 10:28:20', '2026-02-12 22:04:49'),
