(523, 34, 'Chapter III', '[\"Well-justified and systematically selected; shows thoughtful planning and alignment with the study\\u2019s purpose\",\"Sampling method is described with clear rationale and participant relevance\",\"Described briefly with weak rationale or fit\",\"Sampling approach is missing, unjustified, or inappropriate\"]', 8, 0, NULL, NULL, '2025-12-05 03:45:34', '2025-12-05 03:45:34', 0),
(524, 34, 'Chapter III', '[\"Clearly follows a structured model (e.g., Agile, SDLC) with well-explained development phases, roles, and iterations\",\"Identifies an organized process or model; explains phases of development\",\"Process is mentioned but lacks structure or coherence (e.g., unclear use of models like Agile\\/Waterfall)\",\"Development process is missing, disorganized, or inappropriate (e.g., no methodology used)\"]', 9, 0, NULL, NULL, '2025-12-05 03:45:34', '2025-12-05 03:45:34', 0),
(525, 34, 'Chapter III', '[\"Well-structured and technically sound system architecture; clearly shows components, flow, and integration logic\",\"Provides basic structure and understandable architecture diagram\",\"Architecture is present but unclear or lacks technical coherence\",\"Absent or contains irrelevant\\/confusing diagrams or explanations\"]', 10, 0, NULL, NULL, '2025-12-05 03:45:34', '2025-12-05 03:45:34', 0),
(526, 34, 'Content – Quality of the Developed System (20%)', '[\"\",\"\",\"\",\"\"]', 11, 0, NULL, NULL, '2025-12-05 03:45:34', '2025-12-05 03:45:34', 1),
(527, 34, 'Modules and Features Implementation', '[\"All core modules are complete, integrated, and align well with project objectives\",\"Most modules are implemented and function as intended\",\"Some modules are working; lacks completeness or integration\",\"Very few features\\/modules are implemented; most are missing or do not work\"]', 12, 0, NULL, NULL, '2025-12-05 03:45:34', '2025-12-05 03:45:34', 0),
(528, 34, 'User Interface & Navigation', '[\"Highly intuitive, visually consistent, and user-friendly interface\",\"UI is clean and usable with minor inconsistencies\",\"Basic layout and working navigation, but lacks consistency or usability\",\"Interface is confusing or unattractive; navigation is broken or unclear\"]', 13, 0, NULL, NULL, '2025-12-05 03:45:34', '2025-12-05 03:45:34', 0),
(529, 34, 'Performance', '[\"Smooth, fast, and stable system; handles load, input, and errors efficiently\",\"Acceptable performance; generally stable and responsive\",\"Occasionally slow or error-prone; inconsistent handling of input\",\"Very poor performance; system is slow, unresponsive, or crashes frequently\"]', 14, 0, NULL, NULL, '2025-12-05 03:45:34', '2025-12-05 03:45:34', 0),
(530, 34, 'System Reliability & Error Handling', '[\"Highly robust; handles exceptions, validates input, and avoids crashes gracefully\",\"Works reliably with some input validation and error alerts\",\"Basic reliability but lacks input checks or error feedback\",\"System frequently fails; no validation or feedback\"]', 15, 0, NULL, NULL, '2025-12-05 03:45:34', '2025-12-05 03:45:34', 0),
(531, 34, 'Technical Complexity', '[\"Impressive technical depth or creative integration of advanced tools and logic\",\"Demonstrates thoughtful use of tools, logic, or external services\",\"Some effort shown, but implementation is mostly standard\",\"Very basic; no technical challenge or creativity involved\"]', 16, 0, NULL, NULL, '2025-12-05 03:45:34', '2025-12-05 03:45:34', 0),
(532, 24, 'Content – Quality of the Developed System (20%)', '[\"\",\"\",\"\",\"\"]', 0, 0, NULL, NULL, '2025-12-05 03:46:03', '2025-12-05 03:46:03', 1),
(533, 24, 'Chapter I', '[\"Thorough, well articulated context;  strongly justifies the  study with relevant  support\",\"Provides clear and relevant background; rationale is present but may lack depth\",\"Provides minimal context with limited connection to the problem; lacks depth\",\"Lacks clarity, relevance, or justification; context is missing or inappropriate\"]', 1, 0, NULL, NULL, '2025-12-05 03:46:03', '2025-12-05 03:46:03', 0),
(534, 24, 'Chapter I', '[\"Objectives are precise, measurable, and clearly aligned with the research problem\",\"Objectives are clear and aligned with the problem statement\",\"Objectives are stated but unclear or not aligned with the problem\",\"Objectives are vague, irrelevant, or missing\"]', 2, 0, NULL, NULL, '2025-12-05 03:46:03', '2025-12-05 03:46:03', 0),
(535, 24, 'Chapter I', '[\"Strong justification of the study\\u2019s importance; clearly identifies impact and beneficiaries\",\"Adequately explains importance and identifies key beneficiaries\",\"Minimally explains importance; beneficiaries are unclear\",\"No clear value to stakeholders; lacks justification or impact\"]', 3, 0, NULL, NULL, '2025-12-05 03:46:03', '2025-12-05 03:46:03', 0),
(536, 24, 'Chapter I', '[\"Scope and limitations are specific, realistic, and critically analyzed in the context of the study\",\"Scope and limitations are clearly defined and relevant\",\"Scope and limitations are present but lack detail or clarity\",\"Scope is vague or too broad; limitations not identified or irrelevant\"]', 4, 0, NULL, NULL, '2025-12-05 03:46:03', '2025-12-05 03:46:03', 0),
(537, 24, 'Chapter II', '[\"Well-curated, up-todate, and highly relevant sources; shows clear synthesis and strong critical insight connecting to the study\",\"Adequate selection of relevant sources; demonstrates synthesis and some critical thinking\",\"Limited and weakly connected sources; minimal synthesis of ideas\",\"Lacks relevant sources or contains outdated\\/irrelevant literature; no synthesis or connection to study\"]', 5, 0, NULL, NULL, '2025-12-05 03:46:03', '2025-12-05 03:46:03', 0),
(538, 24, 'Chapter II', '[\"Strongly developed, insightful framework; clearly demonstrates the study\'s direction and theoretical foundation\",\"Clearly presented with visual and narrative explanation; ogically aligned with objectives\",\"Present but vague; weak linkage to study or confusing flow\",\"Absent, unclear, or inappropriate; lacks coherence and logical structure\"]', 6, 0, NULL, NULL, '2025-12-05 03:46:03', '2025-12-05 03:46:03', 0),
(539, 24, 'Chapter III', '[\"Strongly articulated design; logically aligned with study goals and appropriate for the project type\",\"Clearly described and generally fits the nature of the study\",\"Design is stated but lacks detail or partial relevance to the objectives\",\"No clear design or methodology; lacks direction or coherence\"]', 7, 0, NULL, NULL, '2025-12-05 03:46:03', '2025-12-05 03:46:03', 0),
(540, 24, 'Chapter III', '[\"Well-justified and systematically selected; shows thoughtful planning and alignment with the study\\u2019s purpose\",\"Sampling method is described with clear rationale and participant relevance\",\"Described briefly with weak rationale or fit\",\"Sampling approach is missing, unjustified, or inappropriate\"]', 8, 0, NULL, NULL, '2025-12-05 03:46:03', '2025-12-05 03:46:03', 0),
(541, 24, 'Chapter III', '[\"Clearly follows a structured model (e.g., Agile, SDLC) with well-explained development phases, roles, and iterations\",\"Identifies an organized process or model; explains phases of development\",\"Process is mentioned but lacks structure or coherence (e.g., unclear use of models like Agile\\/Waterfall)\",\"Development process is missing, disorganized, or inappropriate (e.g., no methodology used)\"]', 9, 0, NULL, NULL, '2025-12-05 03:46:03', '2025-12-05 03:46:03', 0),
(542, 24, 'Chapter III', '[\"Well-structured and technically sound system architecture; clearly shows components, flow, and integration logic\",\"Provides basic structure and understandable architecture diagram\",\"Architecture is present but unclear or lacks technical coherence\",\"Absent or contains irrelevant\\/confusing diagrams or explanations\"]', 10, 0, NULL, NULL, '2025-12-05 03:46:03', '2025-12-05 03:46:03', 0),
(543, 24, 'Content – Quality of the Developed System (20%)', '[\"\",\"\",\"\",\"\"]', 11, 0, NULL, NULL, '2025-12-05 03:46:03', '2025-12-05 03:46:03', 1),
(544, 24, 'Modules and Features Implementation', '[\"All core modules are complete, integrated, and align well with project objectives\",\"Most modules are implemented and function as intended\",\"Some modules are working; lacks completeness or integration\",\"Very few features\\/modules are implemented; most are missing or do not work\"]', 12, 0, NULL, NULL, '2025-12-05 03:46:03', '2025-12-05 03:46:03', 0),
